main{flex:1;display:flex;justify-content:center;padding:2rem 1rem}
.panel{background:#fff;border-radius:8px;box-shadow:0 2px 12px rgba(0,0,0,.08);padding:2rem;width:100%;max-width:640px}
.panel h2{font-size:1.5rem;margin-bottom:.25rem;color:#0b1d3a}
.panel p.sub{font-size:.9rem;color:#555;margin-bottom:1.5rem}
