.toggle-pw:focus{outline:2px solid #e67e22}
.chk-row{display:flex;align-items:flex-start;gap:.5rem;margin-top:.25rem}
.chk-row input{margin-top:.3rem;width:auto}
.chk-row label{font-weight:400;font-size:.875rem;margin-bottom:0}
button.submit{display:inline-block;background:#e67e22;color:#fff;border:none;padding:.7rem 2rem;font-size:1rem;font-weight:600;border-radius:4px;cursor:pointer;margin-top:1rem;transition:background .15s}
button.submit:hover{background:#cf6d17}
