label .req{color:#c0392b;margin-left:2px}
input[type="text"],input[type="email"],input[type="date"],input[type="password"]{width:100%;padding:.55rem .75rem;border:1px solid #bbb;border-radius:4px;font-size:1rem;transition:border-color .15s}
input:focus{outline:none;border-color:#e67e22;box-shadow:0 0 0 2px rgba(230,126,34,.25)}
input.invalid{border-color:#c0392b}
input.valid{border-color:#27ae60}
.err{font-size:.8rem;color:#c0392b;min-height:1.1em;margin-top:.2rem}
.pw-wrap{position:relative}
.pw-wrap input{padding-right:2.5rem}
.toggle-pw{position:absolute;right:.5rem;top:50%;transform:translateY(-50%);background:none;border:none;cursor:pointer;font-size:.8rem;color:#0b1d3a;padding:2px 4px;border-radius:3px}
.toggle-pw:focus{outline:2px solid #e67e22}
.chk-row{display:flex;align-items:flex-start;gap:.5rem;margin-top:.25rem}
.chk-row input{margin-top:.3rem;width:auto}
.chk-row label{font-weight:400;font-size:.875rem;margin-bottom:0}
button.submit{display:inline-block;background:#e67e22;color:#fff;border:none;padding:.7rem 2rem;font-size:1rem;font-weight:600;border-radius:4px;cursor:pointer;margin-top:1rem;transition:background .15s}
button.submit:hover{background:#cf6d17}
button.submit:focus{outline:2px solid #0b1d3a;outline-offset:2px}
button.submit:disabled{opacity:.6;cursor:not-allowed}
.msg{margin-top:1rem;padding:.75rem;border-radius:4px;font-size:.9rem;display:none}
.msg.success{display:block;background:#d4edda;color:#155724;border:1px solid #c3e6cb}
.msg.error{display:block;background:#f8d7da;color:#721c24;border:1px solid #f5c6cb}
@media(max-width:560px){.form-grid{grid-template-columns:1fr}.panel{padding:1.25rem}}
</style>
