<header><h1><span class="accent">&#9670;</span> Public Service Registration</h1></header>
<main>
<div class="panel">
<h2>Create Account</h2>
<p class="sub">All fields marked with * are required.</p>
<form id="regForm" novalidate autocomplete="on">
<div class="form-grid">
<div>
<label for="username">Username <span class="req">*</span></label>
<input type="text" id="username" name="username" required autocomplete="username" aria-describedby="usernameErr">
<div class="err" id="usernameErr" role="alert"></div>
</div>
<div>
<label for="email">Email <span class="req">*</span></label>
<input type="email" id="email" name="email" required autocomplete="email" aria-describedby="emailErr">
<div class="err" id="emailErr" role="alert"></div>
</div>
<div>
<label for="dob">Date of Birth</label>
<input type="date" id="dob" name="dob" autocomplete="bday" aria-describedby="dobErr">
<div class="err" id="dobErr" role="alert"></div>
</div>
<div></div>
<div>
<label for="password">Password <span class="req">*</span></label>
<div class="pw-wrap">
<input type="password" id="password" name="new-password" required autocomplete="new-password" aria-describedby="passwordErr">
<button type="button" class="toggle-pw" id="pwToggle" aria-label="Show password">Show</button>
</div>
<div class="err" id="passwordErr" role="alert"></div>
</div>
<div>
<label for="confirm">Confirm Password <span class="req">*</span></label>
<div class="pw-wrap">
<input type="password" id="confirm" name="confirm-password" required autocomplete="new-password" aria-describedby="confirmErr">
</div>
<div class="err" id="confirmErr" role="alert"></div>
</div>
<div class="full chk-row">
<input type="checkbox" id="tos" name="tos" required aria-describedby="tosErr">
<label for="tos">I accept the <strong>Terms of Service</strong> and <strong>Privacy Policy</strong> <span class="req">*</span></label>
</div>
<div class="full"><div class="err" id="tosErr" role="alert"></div></div>
<div class="full">
<button type="submit" class="submit">Register</button>
<div class="msg" id="formMsg" role="status" aria-live="polite"></div>
</div>
</div>
</form>
</div>
</main>
<script>
(function(){
var KEY='reg_users_v1';
function getUsers(){try{return JSON.parse(localStorage.getItem(KEY))||[];}catch(e){return[];}}
function saveUser(u){var list=getUsers();list.push(u);localStorage.setItem(KEY,JSON.stringify(list));}
function exists(username,email){var list=getUsers();var un=username.toLowerCase(),em=email.toLowerCase();for(var i=0;i<list.length;i++){if(list[i].username===un||list[i].email===em)return list[i];}return null;}
var form=document.getElementById('regForm');
var fields={username:document.getElementById('username'),email:document.getElementById('email'),dob:document.getElementById('dob'),password:document.getElementById('password'),confirm:document.getElementById('confirm'),tos:document.getElementById('tos')};
var errs={username:document.getElementById('usernameErr'),email:document.getElementById('emailErr'),dob:document.getElementById('dobErr'),password:document.getElementById('passwordErr'),confirm:document.getElementById('confirmErr'),tos:document.getElementById('tosErr')};
var msg=document.getElementById('formMsg');
function setErr(name,text){errs[name].textContent=text;fields[name].classList.toggle('invalid',!!text);fields[name].classList.toggle('valid',!text&&fields[name].value.trim()!=='');}
function clearAll(){Object.keys(errs).forEach(function(k){setErr(k,'');});msg.className='msg';msg.textContent='';msg.style.display='none';}
function validateField(name){
var v=fields[name].value;
if(name==='username'){
var t=v.trim();
if(!t){setErr('username','Username is required.');return false;}
if(t.length<3){setErr('username','Username must be at least 3 characters.');return false;}
if(t.length>20){setErr('username','Username must be at most 20 characters.');return false;}
if(!/^[a-zA-Z]/.test(t)){setErr('username','Username must start with a letter.');return false;}
if(!/^[a-zA-Z][a-zA-Z0-9_]*$/.test(t)){setErr('username','Only letters, numbers, and underscores allowed.');return false;}
setErr('username','');return true;
}
if(name==='email'){
var e=v.trim();
if(!e){setErr('email','Email is required.');return false;}
if(/\s/.test(e)){setErr('email','Email cannot contain whitespace.');return false;}
var parts=e.split('@');
if(parts.length!==2||!parts[0]||!parts[1]){setErr('email','Enter a valid email address.');return false;}
var local=parts[0],domain=parts[1];
if(/^\./.test(local)||/\.$/.test(local)||/\.\./.test(local)){setErr('email','Invalid local part in email.');return false;}
var labels=domain.split('.');
if(labels.length<2){setErr('email','Domain must have at least two labels.');return false;}
for(var i=0;i<labels.length;i++){var l=labels[i];if(!l||/^-/.test(l)||/-$/.test(l)){setErr('email','Invalid domain label.');return false;}}
setErr('email','');return true;
}
if(name==='dob'){
if(v){var d=new Date(v+'T00:00:00');if(isNaN(d.getTime())){setErr('dob','Enter a valid date.');return false;}var iso=d.toISOString().slice(0,10);if(iso!==v){setErr('dob','Enter a valid date.');return false;}}
setErr('dob','');return true;
}
if(name==='password'){
if(!v){setErr('password','Password is required.');return false;}
if(v.length<10){setErr('password','Password must be at least 10 characters.');return false;}
if(v.length>64){setErr('password','Password must be at most 64 characters.');return false;}
if(!/[a-zA-Z]/.test(v)){setErr('password','Password must contain at least one letter.');return false;}
if(!/[0-9]/.test(v)){setErr('password','Password must contain at least one digit.');return false;}
setErr('password','');return true;
}
if(name==='confirm'){
if(!v){setErr('confirm','Please confirm your password.');return false;}
if(v!==fields.password.value){setErr('confirm','Passwords do not match.');return false;}
setErr('confirm','');return true;
}
if(name==='tos'){
if(!fields.tos.checked){setErr('tos','You must accept the terms.');return false;}
setErr('tos','');return true;
}
return true;
}
Object.keys(fields).forEach(function(k){
var el=fields[k];
var evt=k==='tos'?'change':'blur';
el.addEventListener(evt,function(){validateField(k);});
if(k!=='tos')el.addEventListener('input',function(){if(el.classList.contains('invalid'))validateField(k);});
});
var pwBtn=document.getElementById('pwToggle');
pwBtn.addEventListener('click',function(){
var show=fields.password.type==='password';
fields.password.type=show?'text':'password';
fields.confirm.type=show?'text':'password';
pwBtn.textContent=show?'Hide':'Show';
pwBtn.setAttribute('aria-label',show?'Hide password':'Show password');
});
form.addEventListener('submit',function(e){
e.preventDefault();
clearAll();
var valid=true;
['username','email','dob','password','confirm','tos'].forEach(function(k){if(!validateField(k))valid=false;});
if(!valid){
msg.className='msg error';
msg.textContent='There is an error with your input. Please correct the invalid fields below.';
msg.style.display='block';
var first=form.querySelector('.invalid');
if(first)first.focus();
return;
}
var un=fields.username.value.trim();
var em=fields.email.value.trim().toLowerCase();
var dup=exists(un,em);
if(dup){
var reason=[];
if(dup.username===un.toLowerCase())reason.push('username');
if(dup.email===em)reason.push('email');
msg.className='msg error';
msg.textContent='An account with this '+reason.join(' and ')+' already exists. Please choose different credentials.';
msg.style.display='block';
if(reason.indexOf('username')>=0)setErr('username','This username is already registered.');
if(reason.indexOf('email')>=0)setErr('email','This email is already registered.');
var first=form.querySelector('.invalid');
if(first)first.focus();
return;
}
saveUser({username:un,email:em,dob:fields.dob.value||null,registered:new Date().toISOString()});
msg.className='msg success';
msg.textContent='Registration successful! Welcome, '+un+'.';
msg.style.display='block';
form.reset();
Object.keys(fields).forEach(function(k){fields[k].classList.remove('valid','invalid');});
fields.password.type='password';
fields.confirm.type='password';
pwBtn.textContent='Show';
pwBtn.setAttribute('aria-label','Show password');
});
})();
</script>
</body>
</html>


